import React, { useState } from 'react';
import api from '../utils/api';

const AddOrder = ({ onOrderAdded }) => {
  const [formData, setFormData] = useState({
    restaurantName: '',
    cuisineType: '',
    menuItemName: '',
    menuItemDescription: '',
    menuItemPrice: '',
    quantity: '',
    orderStatus: ''
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.restaurantName.trim() || !formData.menuItemName.trim() || 
        !formData.menuItemPrice || !formData.quantity) {
      alert('Please fill in required fields: Restaurant Name, Menu Item Name, Price, and Quantity');
      return;
    }

    try {
      await api.post('/orders', {
        ...formData,
        cuisineType: formData.cuisineType || 'Not specified',
        menuItemDescription: formData.menuItemDescription || 'No description',
        orderStatus: formData.orderStatus || 'Pending',
        menuItemPrice: parseFloat(formData.menuItemPrice),
        quantity: parseInt(formData.quantity)
      });

      alert('Order submitted successfully!');

      setFormData({
        restaurantName: '',
        cuisineType: '',
        menuItemName: '',
        menuItemDescription: '',
        menuItemPrice: '',
        quantity: '',
        orderStatus: ''
      });

      onOrderAdded();
    } catch (error) {
      console.error('Error adding order:', error);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="text"
        name="restaurantName"
        placeholder="Restaurant Name *"
        value={formData.restaurantName}
        onChange={handleChange}
        required
      />
      <input
        type="text"
        name="cuisineType"
        placeholder="Cuisine Type"
        value={formData.cuisineType}
        onChange={handleChange}
      />
      <input
        type="text"
        name="menuItemName"
        placeholder="Menu Item Name *"
        value={formData.menuItemName}
        onChange={handleChange}
        required
      />
      <input
        type="text"
        name="menuItemDescription"
        placeholder="Item Description"
        value={formData.menuItemDescription}
        onChange={handleChange}
      />
      <input
        type="number"
        name="menuItemPrice"
        placeholder="Price *"
        value={formData.menuItemPrice}
        onChange={handleChange}
        min="0"
        step="0.01"
        required
      />
      <input
        type="number"
        name="quantity"
        placeholder="Quantity *"
        value={formData.quantity}
        onChange={handleChange}
        min="1"
        required
      />
      <input
        type="text"
        name="orderStatus"
        placeholder="Order Status"
        value={formData.orderStatus}
        onChange={handleChange}
      />
      <button type="submit">Submit Order</button>
    </form>
  );
};

export default AddOrder;
